j := 0;
WHILE j < count DO
    cIdx := LOWER_BOUND(channels,1) + j;
    // Need ensure j within channel array? Caller provides count <= smaller length. Could optionally check UPPER_BOUND? But no need. However if count negative, while not run.
    IF channels[cIdx].enable THEN
        mode := channels[cIdx].measuringMode; // read
        IF (mode <> 0) AND (mode <> 1) AND (mode <> 2) THEN
            channels[cIdx].retVal := 16#8001;
            // preserve outputValue: do not write
        ELSIF channels[cIdx].hiLIM <= channels[cIdx].loLIM THEN
            channels[cIdx].retVal := 16#8002;
        ELSE
            // valid
            aIdx := LOWER_BOUND(analogValues,1) + j;
            raw := analogValues[aIdx];
            IF mode = 0 THEN
                lo := channels[cIdx].loLIM;
                hi := channels[cIdx].hiLIM;
                IF channels[cIdx].bipolar THEN
                    outVal := lo + ((INT_TO_REAL(raw) + 27648.0) / 55296.0) * (hi - lo);
                ELSE
                    outVal := lo + (INT_TO_REAL(raw) / 27648.0) * (hi - lo);
                END_IF;
            ELSIF mode = 1 THEN
                outVal := INT_TO_REAL(raw) / 10.0;
            ELSE // mode = 2
                outVal := INT_TO_REAL(raw) / 100.0;
            END_IF;
            channels[cIdx].retVal := 16#0000;
            channels[cIdx].outputValue := outVal;
        END_IF;
    END_IF;
    j := j + 1;
END_WHILE;

